import type { ReactElement, SVGProps } from 'react';

/**
 * Иконки DS как React-компоненты (currentColor), перенесены как контуры
 * путей из apps/web/src/shared/icons/*.svg (файлы не копируются). Размер по
 * умолчанию 24, переопределяется через width/height или CSS font-size-подобный
 * контекст не используется — только явные пропы.
 */
export type IconProps = SVGProps<SVGSVGElement>;

function iconDefaults(viewBox: string) {
  return { width: 24, height: 24, viewBox, fill: 'none', xmlns: 'http://www.w3.org/2000/svg' } as const;
}

/** Шеврон влево — используется и как «назад». */
export function ChevronLeftIcon(props: IconProps): ReactElement {
  return (
    <svg {...iconDefaults('0 0 24 24')} {...props}>
      <path
        d="M15 5L8.41 11.59a2 2 0 0 0 0 2.82L15 21"
        stroke="currentColor"
        strokeWidth="1.8"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

